using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using Monja;
class EngineTests {
 static int count;static void Check(bool ok,string label){if(!ok)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static int Main(){try{var ctx=new Context{Book="Book.xlsx",Sheet="入力",Sheets=new List<string>{"入力","集計"}};ctx.Names["Amount"]="=入力!B5";ctx.Tables["Sales"]=new TableInfo{Sheet="入力",Address="A1:C100",Columns=new[]{"ID","Price","Qty"}};var target=new Location{Book=ctx.Book,Sheet=ctx.Sheet,Address="D10",Kind="cell"};Func<string,List<Edge>> parse=f=>FormulaParser.Parse(new FormulaInput{Text=f,Target=target},ctx);
 Check(parse("=A1+$B$5+C$2+$D3+A1:C100").Count==5,"relative absolute mixed range");Check(parse("='Data Sheet'!A1+[Other.xlsx]Sheet1!B2")[1].Source.Book=="Other.xlsx","sheet external");Check(parse("=\"A1\"").Count==0,"literal exclusion");Check(parse("=LOG10(A1)").Count==1,"function exclusion");Check(parse("=Amount")[0].Source.Address=="B5","defined name");Check(parse("=Sales[Price]")[0].Source.Address=="B2:B100","table");Check(parse("=SUM(Sales)").Any(e=>e.Source.Address=="A2:C100"),"bare table formula");Check(FormulaParser.Parse(new FormulaInput{Text="Sales",Kind="pivot",Target=target},ctx).Any(e=>e.Source.Address=="A1:C100"),"bare table pivot");Check(parse("=OFFSET(A1,1,0)").All(e=>e.Certainty!="confirmed"),"dynamic certainty");Check(parse("=SUM(入力:集計!A1)").Count==2,"3D");Check(parse("=A1#")[0].Certainty=="estimated","spill");
 var cycle=FormulaParser.Parse(new FormulaInput{Text="=B1",Target=new Location{Book=ctx.Book,Sheet=ctx.Sheet,Address="A1"}},ctx);cycle.AddRange(FormulaParser.Parse(new FormulaInput{Text="=A1",Target=new Location{Book=ctx.Book,Sheet=ctx.Sheet,Address="B1"}},ctx));Check(Graph.Query(cycle,new Location{Book=ctx.Book,Sheet=ctx.Sheet,Address="A1"},true,true).Count==2,"cycle");Check(Graph.Csv(parse("=A1")).Contains("\"'=A1\""),"CSV injection");
 var vba=VbaParser.Parse("Sub Test()\nWorksheets(\"入力\").Range(\"B5\").Value = 3\nx = Worksheets(\"入力\").Cells(5, 2).Value\nRange(variable).ClearContents\nSelection.ClearContents\nEnd Sub",ctx.Book,"Module1",null);Check(vba.Any(e=>e.Kind=="vbaWrite"&&e.Target.Address=="B5"),"VBA write");Check(vba.Any(e=>e.Kind=="vbaRead"&&e.Source.Address=="B5"),"VBA Cells read");Check(vba.Any(e=>e.Kind=="vbaRange"&&e.Certainty=="unknown"),"VBA dynamic");Check(vba.All(e=>(e.Target.Procedure??e.Source.Procedure)=="Test"),"VBA procedure");Check(VbaParser.Parse("'Range(\"A1\")\nx=\"Range(\"\"A1\"\")\"",ctx.Book,"Module2",null).Count==0,"VBA comment/string exclusion");
 foreach(int n in new[]{10000,100000}){long before=GC.GetTotalMemory(true);var watch=Stopwatch.StartNew();int total=0;for(int i=1;i<=n;i++)total+=parse("=A"+i).Count;Check(total==n,"performance "+n);Console.WriteLine("PERF "+n+" "+watch.ElapsedMilliseconds+"ms heapDelta="+(GC.GetTotalMemory(false)-before));}var comparison=VbaParser.Parse("Sub Compare()\nIf Worksheets(\"入力\").Range(\"B5\").Value = 3 Then x=1\nEnd Sub",ctx.Book,"Module1",null);Check(comparison.All(e=>e.Kind=="vbaRead"),"VBA comparison is read, not write");string csvFile=System.IO.Path.GetFullPath("dist/verification/vsto/results-csv.csv");System.IO.File.WriteAllText(csvFile,Graph.Csv(parse("=A1")),new System.Text.UTF8Encoding(true));Check(System.IO.File.ReadAllBytes(csvFile).Take(3).SequenceEqual(new byte[]{239,187,191}),"CSV UTF-8 BOM");Console.WriteLine("Passed: "+count);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}

